-- Case IB complexo: venda da Aurora Formação Profissional (docs/cases/ib-complexo.md). Todos os dados são fictícios.

INSERT INTO cases (id, title, area_id, summary, mission, context, content, status, island_order)
VALUES (
  'ib-complexo',
  'IB completo: a venda da Aurora Formação Profissional',
  'investment-banking',
  'Avalie uma rede de cursos profissionalizantes por DCF, trading comps e transações precedentes e identifique compradores reais.',
  'Avaliar o preço de R$ 90 milhões pedido pelas acionistas, recomendar uma faixa de valor e identificar cinco potenciais compradores.',
  $$Você trabalha como estagiária em uma equipe de M&A que assessora a venda da Aurora Formação Profissional, rede fictícia de cursos profissionalizantes com dez unidades em Minas Gerais e São Paulo. As acionistas desejam vender 100% das ações por R$ 90 milhões, antes de impostos pessoais e despesas da transação. A data-base é 31/12/2025 e os valores estão em R$ milhões. Você vai avaliar o preço por DCF, trading comps e transações precedentes, recomendar uma faixa de valor e pesquisar potenciais compradores.$$,
  $${"resumo": "Em Investment Banking, a equipe de M&A assessora acionistas na venda de uma empresa. O trabalho une análise do negócio, valuation por mais de um método e pesquisa de compradores, e termina em uma recomendação de faixa de valor para o preço pedido. Neste case, você avalia a Aurora Formação Profissional, uma empresa fictícia.", "links": [], "cards": [{"titulo": "Fusões e aquisições (M&A)", "texto": "A equipe de M&A ajuda acionistas a vender, ou empresas a comprar, outras empresas. Cuida da análise, da preparação de materiais, da busca de interessados e do apoio à negociação.", "naPratica": "Antes de falar com compradores, a equipe precisa saber quanto a empresa vale e por quê."}, {"titulo": "DCF: valor pelo fluxo de caixa futuro", "texto": "O fluxo de caixa descontado projeta o dinheiro que a operação deve gerar e o traz a valor presente por uma taxa de desconto (WACC). Depois dos anos projetados, o valor terminal representa a operação estabilizada.", "naPratica": "O resultado depende das premissas. Por isso, a análise testa o que acontece quando elas mudam."}, {"titulo": "Múltiplos de empresas listadas", "texto": "Compara a empresa com outras negociadas em bolsa, usando razões como EV/EBITDA. O enterprise value (EV) soma valor de mercado e dívida e subtrai o caixa.", "naPratica": "Escolher bem os comparáveis importa mais do que fazer a conta: porte, crescimento e modelo de negócio mudam o múltiplo."}, {"titulo": "Transações precedentes", "texto": "Usa os múltiplos pagos em aquisições passadas de empresas parecidas. Esses preços podem embutir prêmio de controle, sinergias esperadas e disputa entre compradores.", "naPratica": "Uma transação com muita sinergia ou disputa pode não servir de referência para outra venda."}, {"titulo": "Compradores estratégicos e financeiros", "texto": "Compradores estratégicos são empresas do setor que buscam crescimento, capacidade ou sinergias. Compradores financeiros, como fundos, buscam retorno com a compra e a venda futura.", "naPratica": "Bons argumentos ligam algo concreto do comprador a algo concreto da empresa vendida."}], "comoSeEntra": {"ondeSeTrabalha": "Bancos de investimento, boutiques de M&A, assessorias financeiras e áreas de desenvolvimento corporativo de grandes empresas.", "formacoes": "Administração, Economia, Engenharia, Ciências Contábeis e áreas próximas.", "vagas": "Estágio em Investment Banking, M&A e finanças corporativas, e programas de estágio de bancos e boutiques.", "oQueAjuda": "Excel, noções de contabilidade e valuation, leitura de notícias de transações e escrita objetiva.", "quandoRecrutam": "Muitos programas abrem uma vez por ano. Acompanhe as páginas de carreira das empresas."}}$$::jsonb,
  'publicado',
  4
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO contents (id, title, type, area_id, summary, body, url, minutes, case_ids) VALUES
($$ibc-dcf$$, $$DCF, WACC e valor terminal$$, $$artigo$$, 'investment-banking', $$Como transformar uma projeção em valor e por que o valor terminal pesa tanto.$$, $$O **fluxo de caixa livre da empresa** é o caixa que a operação gera depois de impostos sobre o resultado operacional, investimentos (CAPEX) e variação do capital de giro; a depreciação, que não é saída de caixa, volta ao fluxo. Cada fluxo é trazido a valor presente pelo **WACC**, a taxa que reflete o retorno exigido por quem financia a empresa. Depois do último ano projetado, o **valor terminal** resume os anos seguintes, em geral supondo que o fluxo cresce a uma taxa constante (perpetuidade). Ele costuma ser grande parte do valor, então vale conferir se a operação estabilizada é coerente com o último ano projetado: crescimento, investimentos e capital de giro devem combinar. O **EV** é a soma dos valores presentes; para chegar ao **valor das ações**, subtraia a dívida e some o caixa excedente. Teste sempre como o resultado muda quando o WACC varia.$$, NULL, 8, '["ib-complexo"]'::jsonb),
($$ibc-multiplos$$, $$Trading comps e transações precedentes$$, $$artigo$$, 'investment-banking', $$Quando usar empresas listadas, quando usar aquisições e por que as duas médias não se misturam.$$, $$**Trading comps** são empresas negociadas em bolsa. O EV delas é o valor de mercado das ações mais a dívida, menos o caixa, e o múltiplo EV/EBITDA compara esse valor com o resultado operacional. **Transações precedentes** são aquisições passadas, com o EV pago. Os dois grupos respondem a perguntas diferentes: o primeiro mostra como o mercado precifica empresas parecidas hoje, sem controle; o segundo mostra o que compradores pagaram para assumir o controle, e pode embutir sinergias, disputa ou venda sob pressão. Por isso, calcule a média de cada grupo separadamente. Ao escolher referências, compare modelo de negócio, porte, crescimento, região e período dos dados. Toda escolha tem semelhanças e limitações, e explicá-las é parte da análise. Para chegar ao valor das ações, aplique o múltiplo ao EBITDA da empresa, obtenha o EV e ajuste pela dívida e pelo caixa.$$, NULL, 7, '["ib-complexo"]'::jsonb),
($$ibc-compradores$$, $$Como pensar em potenciais compradores$$, $$artigo$$, 'investment-banking', $$Compradores estratégicos e financeiros, e como argumentar de forma concreta.$$, $$Um **comprador estratégico** é uma empresa que já atua no setor ou em um setor próximo e pode buscar novos mercados, capacidade, marcas ou economias de escala. Um **comprador financeiro**, como um fundo de private equity, busca retorno: compra, melhora a empresa e vende depois. Para cada nome, ligue um fato sobre o comprador (presença geográfica, estratégia anunciada, compras anteriores, porte) a uma característica da empresa vendida. Evite argumentos genéricos, como apenas dizer que ambos atuam no mesmo setor. Diferencie o que você **pesquisou** em fontes públicas do que é **hipótese** sobre interesse, sinergias ou capacidade de pagar, e indique como confirmar. Registre sempre as fontes. Todo comprador também traz questões a investigar, como sobreposição de unidades, endividamento ou disputas regulatórias.$$, NULL, 6, '["ib-complexo"]'::jsonb)
ON CONFLICT (id) DO NOTHING;

