INSERT INTO tasks (id, case_id, checkpoint_id, title, prompt, fields, support_data, answer_key) VALUES
($$ibc-task-negocio$$, 'ib-complexo', $$ibc-cp-3$$, $$Entenda a Aurora e o preço pedido$$, $$Você é estagiária na equipe de M&A que assessora a venda da Aurora Formação Profissional. As acionistas querem vender 100% das ações por R$ 90 milhões, antes de impostos pessoais e despesas da transação. A Aurora e os comparáveis são fictícios; os valores estão em R$ milhões, salvo indicação, e a data-base é 31/12/2025.

A Aurora oferece cursos profissionalizantes de administração, tecnologia e serviços, em dez unidades próprias em Minas Gerais e São Paulo. Cada unidade comporta, em média, 800 alunos equivalentes por ano. Em 2025, a empresa teve 6.000 alunos equivalentes e recebeu, em média, R$ 9.000 por aluno no ano, já descontadas bolsas e reduções de preço.

Informações reunidas pela equipe:
• Quatro unidades ficam perto de polos logísticos e industriais; as demais atendem regiões urbanas com comércio e serviços.
• Cerca de 60% das turmas ocorrem à noite, e algumas salas têm baixa utilização durante o dia.
• Cerca de 28% dos novos alunos de 2025 vieram por indicação de funcionários de quatro empresas da região, sem contratos de exclusividade ou garantia de matrículas.
• As unidades usam sistemas de matrícula separados; a base única de alunos ainda não foi concluída.
• Os cursos de tecnologia cresceram mais em 2025, mas exigiram atualização de equipamentos.
• A concorrência de cursos on-line aumentou, e a Aurora não tem dados para estimar quantos alunos deixou de captar.
• As fundadoras querem realizar parte do patrimônio e transferir a gestão. A administração acredita que a rede pode crescer, mas reconhece que expansão e atualização exigem investimento.

Os custos variáveis incluem professores horistas, materiais e comissões de venda; os custos fixos incluem aluguéis, equipe permanente, administração e marketing. As duas linhas excluem depreciação e amortização.

Em 31/12/2025: dívida financeira de 18,0; caixa excedente de 4,0; necessidade de capital de giro operacional de 5,4.$$, $$[{"id": "margem_ebitda_2025", "tipo": "numerico", "rotulo": "Margem EBITDA de 2025", "obrigatorio": true, "unidade": "%", "dica": "Use vírgula como separador decimal. Ex.: 12,4"}, {"id": "divida_liquida", "tipo": "numerico", "rotulo": "Dívida líquida em 31/12/2025", "obrigatorio": true, "unidade": "R$ milhões", "dica": "Use vírgula como separador decimal."}, {"id": "pontos_fortes", "tipo": "texto", "rotulo": "Cite dois fatos do enunciado que sustentariam uma tese positiva para a venda e explique por quê.", "obrigatorio": true, "limiteCaracteres": 700}, {"id": "riscos", "tipo": "texto", "rotulo": "Cite dois riscos ou fatores de dependência que um comprador investigaria e explique por quê.", "obrigatorio": true, "limiteCaracteres": 700}, {"id": "o_que_falta", "tipo": "texto", "rotulo": "Que informação ainda é desconhecida e faria diferença na avaliação?", "obrigatorio": true, "limiteCaracteres": 450}]$$::jsonb, $${"titulo": "Histórico financeiro da Aurora (R$ milhões)", "colunas": ["2023", "2024", "2025"], "linhas": [{"rotulo": "Receita líquida", "celulas": [{"texto": "38,0", "valor": 38.0}, {"texto": "45,0", "valor": 45.0}, {"texto": "54,0", "valor": 54.0}]}, {"rotulo": "Custos variáveis", "celulas": [{"texto": "15,2", "valor": 15.2}, {"texto": "18,0", "valor": 18.0}, {"texto": "21,6", "valor": 21.6}]}, {"rotulo": "Custos fixos e despesas operacionais", "celulas": [{"texto": "16,6", "valor": 16.6}, {"texto": "18,4", "valor": 18.4}, {"texto": "20,9", "valor": 20.9}]}, {"rotulo": "EBITDA", "celulas": [{"texto": "6,2", "valor": 6.2}, {"texto": "8,6", "valor": 8.6}, {"texto": "11,5", "valor": 11.5}]}, {"rotulo": "Depreciação e amortização", "celulas": [{"texto": "1,9", "valor": 1.9}, {"texto": "2,25", "valor": 2.25}, {"texto": "2,7", "valor": 2.7}]}, {"rotulo": "EBIT", "celulas": [{"texto": "4,3", "valor": 4.3}, {"texto": "6,35", "valor": 6.35}, {"texto": "8,8", "valor": 8.8}]}]}$$::jsonb, $${"referencias": {"margem_ebitda_2025": 21.3, "divida_liquida": 14.0, "tolerancia": 0.1}, "avaliacao": "Pontos fortes aceitáveis: crescimento de receita e EBITDA nos três anos, margem EBITDA subindo (16,3% em 2023, 19,1% em 2024, 21,3% em 2025), capacidade ociosa diurna, unidades em polos industriais, tecnologia crescendo. Riscos aceitáveis: concentração de 28% dos novos alunos em quatro empresas sem contrato, concorrência on-line sem dados, sistemas separados, necessidade de CAPEX e dependência das fundadoras na gestão. Exigir conexão com os fatos do enunciado, não listas genéricas."}$$::jsonb),
($$ibc-task-projecao$$, 'ib-complexo', $$ibc-cp-4$$, $$Projeção operacional$$, $$Projete a operação da Aurora para 2026 a 2030 com as premissas da administração.

• O crescimento de alunos incorpora captação e evasão. O crescimento da receita por aluno já considera reajustes e descontos.
• Uma nova unidade, com capacidade para 800 alunos equivalentes por ano, será preparada em 2028 e abrirá no início de 2029. O CAPEX de 2028 inclui R$ 4,0 milhões para sua implantação. Considere a capacidade da nova unidade disponível durante todo o ano de 2029.
• Em 2025, o custo variável médio foi de R$ 3.600 por aluno equivalente, valor que cresce 4% ao ano.
• Os custos fixos e despesas de 2025 (20,9) crescem 5% ao ano.
• A nova unidade adiciona R$ 1,5 milhão de custos fixos em 2029. Em 2030, esses custos também crescem 5%.
• Parta dos dados de 2025 do histórico financeiro e do enunciado anterior (6.000 alunos equivalentes e R$ 9.000 de receita por aluno).

Verifique se a projeção de alunos é compatível com a capacidade da rede em cada ano.$$, $$[{"id": "alunos_2030", "tipo": "numerico", "rotulo": "Alunos equivalentes em 2030", "obrigatorio": true, "unidade": "alunos", "dica": "Use vírgula como separador decimal."}, {"id": "receita_2030", "tipo": "numerico", "rotulo": "Receita líquida de 2030", "obrigatorio": true, "unidade": "R$ milhões", "dica": "Use vírgula como separador decimal."}, {"id": "ebitda_2026", "tipo": "numerico", "rotulo": "EBITDA de 2026", "obrigatorio": true, "unidade": "R$ milhões", "dica": "Use vírgula como separador decimal."}, {"id": "ebitda_2030", "tipo": "numerico", "rotulo": "EBITDA de 2030", "obrigatorio": true, "unidade": "R$ milhões", "dica": "Use vírgula como separador decimal."}, {"id": "capacidade", "tipo": "opcao", "rotulo": "A projeção de alunos cabe na capacidade da rede em todos os anos de 2026 a 2030?", "obrigatorio": true, "opcoes": ["Sim, em todos os anos", "Não, falta capacidade em 2028", "Não, falta capacidade em 2029", "Não, falta capacidade em 2030"]}, {"id": "capacidade_justificativa", "tipo": "texto", "rotulo": "Explique sua resposta sobre a capacidade, citando os números de 2028 e 2029.", "obrigatorio": true, "limiteCaracteres": 500}]$$::jsonb, $${"titulo": "Premissas da administração (cenário-base)", "colunas": ["2026", "2027", "2028", "2029", "2030"], "linhas": [{"rotulo": "Crescimento dos alunos equivalentes", "celulas": [{"texto": "10%", "valor": 10}, {"texto": "9%", "valor": 9}, {"texto": "7%", "valor": 7}, {"texto": "5%", "valor": 5}, {"texto": "4%", "valor": 4}]}, {"rotulo": "Crescimento da receita anual por aluno", "celulas": [{"texto": "5%", "valor": 5}, {"texto": "4,5%", "valor": 4.5}, {"texto": "4%", "valor": 4}, {"texto": "3,5%", "valor": 3.5}, {"texto": "3,5%", "valor": 3.5}]}, {"rotulo": "CAPEX total (R$ milhões)", "celulas": [{"texto": "5,0", "valor": 5}, {"texto": "5,0", "valor": 5}, {"texto": "9,0", "valor": 9}, {"texto": "5,0", "valor": 5}, {"texto": "5,0", "valor": 5}]}]}$$::jsonb, $${"referencias": {"alunos_2030": 8406, "receita_2030": 92.5, "ebitda_2026": 15.7, "ebitda_2030": 27.4, "capacidade": "Sim, em todos os anos", "tolerancia_relativa": 0.01}, "passoAPasso": "Alunos: 6.600; 7.194; 7.698; 8.082; 8.406 (capacidade 8.000 até 2028 e 8.800 de 2029 em diante). Receita: 62,4; 71,0; 79,1; 85,9; 92,5. Custo variável: 24,7; 28,0; 31,2; 34,0; 36,8. Custos fixos: 21,9; 23,0; 24,2; 26,9 (inclui 1,5); 28,2. EBITDA: 15,7; 20,0; 23,7; 25,0; 27,4.", "observacao": "A rede ocupa 96% da capacidade em 2028 (7.698 de 8.000), próximo do limite; sem a nova unidade, 2029 estouraria a capacidade (8.082 > 8.000)."}$$::jsonb),
($$ibc-task-dcf$$, 'ib-complexo', $$ibc-cp-5$$, $$Fluxo de caixa, valor terminal e EV$$, $$Com a projeção operacional da tarefa anterior, avalie a Aurora por fluxo de caixa descontado.

Premissas de 2026 a 2030:
• Depreciação e amortização: 5% da receita.
• Impostos operacionais: 34% do EBIT.
• Capital de giro operacional ao fim de cada ano: 10% da receita. O capital de giro de 31/12/2025 é 5,4.
• CAPEX: 5,0 em 2026, 5,0 em 2027, 9,0 em 2028, 5,0 em 2029 e 5,0 em 2030.
• WACC: 15% ao ano. Considere fluxos ao final de cada ano.

Operação estabilizada após 2030, com crescimento nominal de 4% ao ano. Para 2031: mantenha o número de alunos e de unidades de 2030; aumente a receita por aluno, o custo variável por aluno e os custos fixos em 4%; mantenha depreciação e amortização em 5% da receita e capital de giro em 10% da receita; considere CAPEX de 7,31% da receita de 2031.

Calcule o fluxo de caixa livre de 2026 a 2030, o valor terminal, o EV e o valor das ações. Dívida financeira: 18,0; caixa excedente: 4,0. Não considere ajustes por arrendamentos, participações minoritárias ou outros ativos.$$, $$[{"id": "fcl_2026", "tipo": "numerico", "rotulo": "Fluxo de caixa livre de 2026", "obrigatorio": true, "unidade": "R$ milhões", "dica": "Use vírgula como separador decimal."}, {"id": "fcl_2030", "tipo": "numerico", "rotulo": "Fluxo de caixa livre de 2030", "obrigatorio": true, "unidade": "R$ milhões", "dica": "Use vírgula como separador decimal."}, {"id": "valor_terminal", "tipo": "numerico", "rotulo": "Valor terminal (em 2030)", "obrigatorio": true, "unidade": "R$ milhões", "dica": "Use vírgula como separador decimal."}, {"id": "ev_dcf", "tipo": "numerico", "rotulo": "Enterprise Value (EV) pelo DCF", "obrigatorio": true, "unidade": "R$ milhões", "dica": "Use vírgula como separador decimal."}, {"id": "equity_dcf", "tipo": "numerico", "rotulo": "Valor das ações pelo DCF", "obrigatorio": true, "unidade": "R$ milhões", "dica": "Use vírgula como separador decimal."}, {"id": "premissa_sensivel", "tipo": "texto", "rotulo": "Qual premissa mais influencia o resultado do DCF e por quê?", "obrigatorio": true, "limiteCaracteres": 500}, {"id": "planilha_dcf", "tipo": "arquivo", "rotulo": "Anexar a aba de DCF (planilha)", "obrigatorio": false, "dica": "PDF, XLSX ou CSV, até 10 MB"}]$$::jsonb, $${"titulo": "Dados de 31/12/2025 (R$ milhões)", "colunas": ["Valor"], "linhas": [{"rotulo": "Dívida financeira", "celulas": [{"texto": "18,0", "valor": 18.0}]}, {"rotulo": "Caixa excedente", "celulas": [{"texto": "4,0", "valor": 4.0}]}, {"rotulo": "Capital de giro operacional", "celulas": [{"texto": "5,4", "valor": 5.4}]}, {"rotulo": "WACC", "celulas": [{"texto": "15%", "valor": 15}]}, {"rotulo": "Crescimento na perpetuidade", "celulas": [{"texto": "4%", "valor": 4}]}]}$$::jsonb, $${"referencias": {"fcl_2026": 5.6, "fcl_2030": 14.0, "valor_terminal": 118.6, "ev_dcf": 89.0, "equity_dcf": 75.0, "tolerancia_relativa": 0.02}, "passoAPasso": "FCL = EBIT x (1 - 34%) + D&A - CAPEX - variação do capital de giro. FCL: 5,60; 8,53; 7,18; 12,26; 14,01. 2031: receita 96,18; EBITDA 28,51; EBIT 23,70; FCL 2031 = 13,05. VT = 13,05 / (15% - 4%) = 118,6; VP do VT = 59,0; VP dos fluxos = 30,0; EV = 89,0; ações = 89,0 - 18,0 + 4,0 = 75,0.", "observacao": "Conferido por cálculo em Python. O preço pedido (90) fica ~20% acima do valor das ações pelo DCF-base (75,0); o EV (89,0) é quase igual ao preço pedido, o que sugere que o pedido compara ações com EV. O valor terminal responde por cerca de 66% do EV."}$$::jsonb),
($$ibc-task-comps$$, 'ib-complexo', $$ibc-cp-6$$, $$Selecione e calcule os trading comps$$, $$Estime o valor da Aurora por múltiplos de empresas listadas. As empresas da tabela são fictícias. Receita e EBITDA são de 2025; valor de mercado das ações, dívida e caixa são de 31/12/2025. O crescimento compara 2025 com 2024.

Selecione três empresas listadas. Para cada escolha, explique uma semelhança e uma limitação em relação à Aurora. Calcule o múltiplo EV/EBITDA de cada empresa selecionada e a média aritmética do grupo. Use essa média para estimar o EV e o valor das ações da Aurora (EBITDA de 2025 de 11,5; dívida financeira de 18,0; caixa excedente de 4,0). Explique uma limitação do método.

Dica: informe as empresas selecionadas e os cálculos; não há uma única seleção correta, mas cada escolha deve ser justificada.$$, $$[{"id": "comp_1", "tipo": "opcao", "rotulo": "Trading comp selecionada 1", "obrigatorio": true, "opcoes": ["T1 — Trilha", "T2 — Ponte", "T3 — Ofício", "T4 — Elo", "T5 — Saber", "T6 — Nuvem"]}, {"id": "comp_2", "tipo": "opcao", "rotulo": "Trading comp selecionada 2", "obrigatorio": true, "opcoes": ["T1 — Trilha", "T2 — Ponte", "T3 — Ofício", "T4 — Elo", "T5 — Saber", "T6 — Nuvem"]}, {"id": "comp_3", "tipo": "opcao", "rotulo": "Trading comp selecionada 3", "obrigatorio": true, "opcoes": ["T1 — Trilha", "T2 — Ponte", "T3 — Ofício", "T4 — Elo", "T5 — Saber", "T6 — Nuvem"]}, {"id": "justificativa_1", "tipo": "texto", "rotulo": "Semelhança e limitação da primeira escolha, em relação à Aurora.", "obrigatorio": true, "limiteCaracteres": 500}, {"id": "justificativa_2", "tipo": "texto", "rotulo": "Semelhança e limitação da segunda escolha, em relação à Aurora.", "obrigatorio": true, "limiteCaracteres": 500}, {"id": "justificativa_3", "tipo": "texto", "rotulo": "Semelhança e limitação da terceira escolha, em relação à Aurora.", "obrigatorio": true, "limiteCaracteres": 500}, {"id": "multiplo_medio_comps", "tipo": "numerico", "rotulo": "Média do EV/EBITDA das três selecionadas", "obrigatorio": true, "unidade": "x", "dica": "Use vírgula como separador decimal. Ex.: 7,3"}, {"id": "ev_comps", "tipo": "numerico", "rotulo": "EV estimado da Aurora por trading comps", "obrigatorio": true, "unidade": "R$ milhões", "dica": "Use vírgula como separador decimal."}, {"id": "equity_comps", "tipo": "numerico", "rotulo": "Valor das ações da Aurora por trading comps", "obrigatorio": true, "unidade": "R$ milhões", "dica": "Use vírgula como separador decimal."}, {"id": "limitacao_comps", "tipo": "texto", "rotulo": "Uma limitação do método de trading comps para avaliar a Aurora.", "obrigatorio": true, "limiteCaracteres": 500}, {"id": "planilha_comps", "tipo": "arquivo", "rotulo": "Anexar a aba de comparáveis (planilha)", "obrigatorio": false, "dica": "PDF, XLSX ou CSV, até 10 MB"}]$$::jsonb, $${"titulo": "Empresas listadas fictícias (R$ milhões, dados de 2025; valor de mercado, dívida e caixa de 31/12/2025)", "colunas": ["Receita", "EBITDA", "Crescimento (%)", "Valor de mercado", "Dívida", "Caixa", "EV da aquisição"], "linhas": [{"rotulo": "T1 — Trilha: cursos profissionais presenciais; unidades próprias em SP e PR; cursos concentrados em administração e logística.", "celulas": [{"texto": "80", "valor": 80}, {"texto": "18", "valor": 18}, {"texto": "15", "valor": 15}, {"texto": "110", "valor": 110}, {"texto": "20", "valor": 20}, {"texto": "4", "valor": 4}, {"texto": "—", "valor": null}]}, {"rotulo": "T2 — Ponte: rede própria de maior porte, presente em cinco estados; diversificou recentemente sua oferta de tecnologia.", "celulas": [{"texto": "140", "valor": 140}, {"texto": "35", "valor": 35}, {"texto": "18", "valor": 18}, {"texto": "235", "valor": 235}, {"texto": "35", "valor": 35}, {"texto": "7", "valor": 7}, {"texto": "—", "valor": null}]}, {"rotulo": "T3 — Ofício: rede regional de cursos profissionais em MG; unidades menores e crescimento mais lento.", "celulas": [{"texto": "50", "valor": 50}, {"texto": "11", "valor": 11}, {"texto": "8", "valor": 8}, {"texto": "60", "valor": 60}, {"texto": "15", "valor": 15}, {"texto": "3", "valor": 3}, {"texto": "—", "valor": null}]}, {"rotulo": "T4 — Elo: rede própria de idiomas; atende adolescentes e adultos; salas com menor necessidade de equipamentos.", "celulas": [{"texto": "75", "valor": 75}, {"texto": "18", "valor": 18}, {"texto": "10", "valor": 10}, {"texto": "115", "valor": 115}, {"texto": "18", "valor": 18}, {"texto": "5", "valor": 5}, {"texto": "—", "valor": null}]}, {"rotulo": "T5 — Saber: rede de franquias de cursos profissionais; recebe royalties e investe pouco nas unidades franqueadas.", "celulas": [{"texto": "100", "valor": 100}, {"texto": "40", "valor": 40}, {"texto": "16", "valor": 16}, {"texto": "390", "valor": 390}, {"texto": "20", "valor": 20}, {"texto": "10", "valor": 10}, {"texto": "—", "valor": null}]}, {"rotulo": "T6 — Nuvem: cursos profissionais on-line; possui plataforma própria e não opera unidades presenciais.", "celulas": [{"texto": "90", "valor": 90}, {"texto": "25", "valor": 25}, {"texto": "28", "valor": 28}, {"texto": "260", "valor": 260}, {"texto": "8", "valor": 8}, {"texto": "12", "valor": 12}, {"texto": "—", "valor": null}]}]}$$::jsonb, $${"multiplos": {"T1": 7.0, "T2": 7.51, "T3": 6.55, "T4": 7.11, "T5": 10.0, "T6": 10.24}, "ev": {"T1": 126, "T2": 263, "T3": 72, "T4": 128, "T5": 400, "T6": 256}, "selecaoDefensavel": ["T1", "T3", "T4"], "mediaDaSelecaoDefensavel": 6.89, "evAurora": 79.2, "acoesAurora": 65.2, "outrasEscolhas": "T2 é defensável (rede própria, tecnologia, mas porte e região distintos). T5 (franquias, margem de 40%) e T6 (on-line, crescimento de 28%) têm modelos diferentes da rede própria presencial da Aurora; aceitar apenas com limitação explícita. T4 é de idiomas, mas tem estrutura de rede própria. Aceitar qualquer seleção com cálculo coerente com as escolhas feitas.", "avaliacao": "Verificar EV = valor de mercado + dívida - caixa, EV/EBITDA por empresa, média simples do grupo, EV da Aurora = média x 11,5 e ações = EV - 18 + 4. Penalizar misturar com transações."}$$::jsonb),
($$ibc-task-transacoes$$, 'ib-complexo', $$ibc-cp-7$$, $$Selecione e calcule as transações precedentes$$, $$Estime o valor da Aurora pelos múltiplos pagos em aquisições. As transações da tabela são fictícias, envolveram 100% das ações e transferência de controle, e ocorreram em 30/09/2025. Receita e EBITDA são dos 12 meses anteriores à transação, antes de sinergias; o crescimento compara esses 12 meses com os 12 meses anteriores.

Selecione duas transações. Para cada escolha, explique uma semelhança e uma limitação em relação à Aurora. Calcule o EV/EBITDA de cada transação selecionada e a média aritmética das duas. Use essa média para estimar o EV e o valor das ações da Aurora (EBITDA de 2025 de 11,5; dívida financeira de 18,0; caixa excedente de 4,0). Não misture este grupo com as empresas listadas. Explique uma limitação do método.$$, $$[{"id": "transacao_1", "tipo": "opcao", "rotulo": "Transação selecionada 1", "obrigatorio": true, "opcoes": ["P1 — Raiz", "P2 — Passo", "P3 — Futura"]}, {"id": "transacao_2", "tipo": "opcao", "rotulo": "Transação selecionada 2", "obrigatorio": true, "opcoes": ["P1 — Raiz", "P2 — Passo", "P3 — Futura"]}, {"id": "justificativa_1", "tipo": "texto", "rotulo": "Semelhança e limitação da primeira escolha, em relação à Aurora.", "obrigatorio": true, "limiteCaracteres": 500}, {"id": "justificativa_2", "tipo": "texto", "rotulo": "Semelhança e limitação da segunda escolha, em relação à Aurora.", "obrigatorio": true, "limiteCaracteres": 500}, {"id": "multiplo_medio_transacoes", "tipo": "numerico", "rotulo": "Média do EV/EBITDA das duas selecionadas", "obrigatorio": true, "unidade": "x", "dica": "Use vírgula como separador decimal. Ex.: 7,3"}, {"id": "ev_transacoes", "tipo": "numerico", "rotulo": "EV estimado da Aurora por transações precedentes", "obrigatorio": true, "unidade": "R$ milhões", "dica": "Use vírgula como separador decimal."}, {"id": "equity_transacoes", "tipo": "numerico", "rotulo": "Valor das ações da Aurora por transações precedentes", "obrigatorio": true, "unidade": "R$ milhões", "dica": "Use vírgula como separador decimal."}, {"id": "limitacao_transacoes", "tipo": "texto", "rotulo": "Uma limitação do método de transações precedentes para avaliar a Aurora.", "obrigatorio": true, "limiteCaracteres": 500}]$$::jsonb, $${"titulo": "Transações precedentes fictícias (R$ milhões, 100% das ações, 30/09/2025; resultados dos 12 meses anteriores, antes de sinergias)", "colunas": ["Receita", "EBITDA", "Crescimento (%)", "Valor de mercado", "Dívida", "Caixa", "EV da aquisição"], "linhas": [{"rotulo": "P1 — Raiz: rede própria no Sudeste; o comprador informou esperar economias administrativas moderadas.", "celulas": [{"texto": "70", "valor": 70}, {"texto": "16", "valor": 16}, {"texto": "14", "valor": 14}, {"texto": "—", "valor": null}, {"texto": "—", "valor": null}, {"texto": "—", "valor": null}, {"texto": "125", "valor": 125}]}, {"rotulo": "P2 — Passo: rede própria regional; adquirida por um fundo em uma sucessão familiar.", "celulas": [{"texto": "45", "valor": 45}, {"texto": "10", "valor": 10}, {"texto": "10", "valor": 10}, {"texto": "—", "valor": null}, {"texto": "—", "valor": null}, {"texto": "—", "valor": null}, {"texto": "67", "valor": 67}]}, {"rotulo": "P3 — Futura: rede própria maior; houve disputa entre compradores e o vencedor anunciou expectativa de sinergias relevantes.", "celulas": [{"texto": "125", "valor": 125}, {"texto": "34", "valor": 34}, {"texto": "23", "valor": 23}, {"texto": "—", "valor": null}, {"texto": "—", "valor": null}, {"texto": "—", "valor": null}, {"texto": "315", "valor": 315}]}]}$$::jsonb, $${"multiplos": {"P1": 7.81, "P2": 6.7, "P3": 9.26}, "selecaoDefensavel": ["P1", "P2"], "mediaDaSelecaoDefensavel": 7.26, "evAurora": 83.4, "acoesAurora": 69.4, "outrasEscolhas": "P3 é mais difícil de defender: porte maior, crescimento de 23% e múltiplo que provavelmente embute disputa entre compradores e sinergias relevantes. Pode ser aceita com essa limitação explícita e justificativa. P2 foi uma sucessão familiar, semelhante ao desejo das fundadoras de transferir a gestão. Aceitar qualquer seleção com cálculo coerente.", "observacao": "Transações não têm múltiplo necessariamente superior ao de bolsa: aqui P1 e P2 ficam próximos aos listados defensáveis."}$$::jsonb),
($$ibc-task-compradores$$, 'ib-complexo', $$ibc-cp-8$$, $$Cinco potenciais compradores$$, $$Pesquise e selecione cinco potenciais compradores reais para a Aurora. Podem ser empresas, grupos educacionais, fundos de investimento ou outros players que você considere relevantes; você não precisa se limitar às empresas fictícias das tabelas.

Para cada comprador: apresente brevemente sua atuação; desenvolva dois argumentos distintos para explicar por que a aquisição poderia fazer sentido; aponte uma possível limitação ou questão a investigar; e inclua as fontes utilizadas.

Os argumentos devem relacionar informações sobre o comprador com características da Aurora (por exemplo, localização das unidades, capacidade ociosa à noite ou durante o dia, cursos de tecnologia, sistemas de matrícula, estágio de crescimento). Evite justificativas genéricas, como apenas dizer que ambos atuam em educação. Diferencie fatos pesquisados de hipóteses sobre interesse, sinergias ou capacidade de aquisição. Se os dados não forem públicos, indique que são pontos a confirmar.$$, $$[{"id": "c1_nome", "tipo": "texto", "rotulo": "Comprador 1: nome", "obrigatorio": true, "limiteCaracteres": 150}, {"id": "c1_atuacao_argumentos", "tipo": "texto", "rotulo": "Comprador 1: atuação resumida e dois argumentos distintos ligados à Aurora", "obrigatorio": true, "limiteCaracteres": 900}, {"id": "c1_limitacao", "tipo": "texto", "rotulo": "Comprador 1: uma limitação ou questão a investigar", "obrigatorio": true, "limiteCaracteres": 400}, {"id": "c1_fontes", "tipo": "texto", "rotulo": "Comprador 1: fontes consultadas", "obrigatorio": true, "limiteCaracteres": 300}, {"id": "c2_nome", "tipo": "texto", "rotulo": "Comprador 2: nome", "obrigatorio": true, "limiteCaracteres": 150}, {"id": "c2_atuacao_argumentos", "tipo": "texto", "rotulo": "Comprador 2: atuação resumida e dois argumentos distintos ligados à Aurora", "obrigatorio": true, "limiteCaracteres": 900}, {"id": "c2_limitacao", "tipo": "texto", "rotulo": "Comprador 2: uma limitação ou questão a investigar", "obrigatorio": true, "limiteCaracteres": 400}, {"id": "c2_fontes", "tipo": "texto", "rotulo": "Comprador 2: fontes consultadas", "obrigatorio": true, "limiteCaracteres": 300}, {"id": "c3_nome", "tipo": "texto", "rotulo": "Comprador 3: nome", "obrigatorio": true, "limiteCaracteres": 150}, {"id": "c3_atuacao_argumentos", "tipo": "texto", "rotulo": "Comprador 3: atuação resumida e dois argumentos distintos ligados à Aurora", "obrigatorio": true, "limiteCaracteres": 900}, {"id": "c3_limitacao", "tipo": "texto", "rotulo": "Comprador 3: uma limitação ou questão a investigar", "obrigatorio": true, "limiteCaracteres": 400}, {"id": "c3_fontes", "tipo": "texto", "rotulo": "Comprador 3: fontes consultadas", "obrigatorio": true, "limiteCaracteres": 300}, {"id": "c4_nome", "tipo": "texto", "rotulo": "Comprador 4: nome", "obrigatorio": true, "limiteCaracteres": 150}, {"id": "c4_atuacao_argumentos", "tipo": "texto", "rotulo": "Comprador 4: atuação resumida e dois argumentos distintos ligados à Aurora", "obrigatorio": true, "limiteCaracteres": 900}, {"id": "c4_limitacao", "tipo": "texto", "rotulo": "Comprador 4: uma limitação ou questão a investigar", "obrigatorio": true, "limiteCaracteres": 400}, {"id": "c4_fontes", "tipo": "texto", "rotulo": "Comprador 4: fontes consultadas", "obrigatorio": true, "limiteCaracteres": 300}, {"id": "c5_nome", "tipo": "texto", "rotulo": "Comprador 5: nome", "obrigatorio": true, "limiteCaracteres": 150}, {"id": "c5_atuacao_argumentos", "tipo": "texto", "rotulo": "Comprador 5: atuação resumida e dois argumentos distintos ligados à Aurora", "obrigatorio": true, "limiteCaracteres": 900}, {"id": "c5_limitacao", "tipo": "texto", "rotulo": "Comprador 5: uma limitação ou questão a investigar", "obrigatorio": true, "limiteCaracteres": 400}, {"id": "c5_fontes", "tipo": "texto", "rotulo": "Comprador 5: fontes consultadas", "obrigatorio": true, "limiteCaracteres": 300}]$$::jsonb, NULL, $${"avaliacao": "Não há lista fechada de compradores. Avaliar: (1) o comprador é real e a descrição é compatível com fontes públicas; (2) dois argumentos distintos, cada um ligando um fato do comprador a um fato da Aurora; (3) limitação ou questão relevante; (4) fontes citadas e distinção entre fato e hipótese; (5) variedade (estratégicos e financeiros). Penalizar justificativas genéricas, fatos inventados e fontes ausentes."}$$::jsonb),
($$ibc-task-conclusao$$, 'ib-complexo', $$ibc-cp-9$$, $$Faixa de valor e recomendação$$, $$Apresente sua conclusão ao comitê de M&A em linguagem objetiva, usando os resultados das tarefas anteriores. Não use uma média dos métodos como recomendação final: explique como pesou cada método.

Informe a faixa de valor que você recomenda para as ações da Aurora, avalie o preço pedido de R$ 90 milhões, aponte os principais pontos positivos e riscos e faça uma sensibilidade simples do DCF ao WACC (14% e 16%, mantendo as demais premissas). Indique três informações a confirmar antes de negociar. Se quiser, anexe sua planilha completa (abas DCF, Comparáveis e Lista de compradores).$$, $$[{"id": "faixa_minima", "tipo": "numerico", "rotulo": "Valor mínimo da faixa recomendada para as ações", "obrigatorio": true, "unidade": "R$ milhões", "dica": "Use vírgula como separador decimal."}, {"id": "faixa_maxima", "tipo": "numerico", "rotulo": "Valor máximo da faixa recomendada para as ações", "obrigatorio": true, "unidade": "R$ milhões", "dica": "Use vírgula como separador decimal."}, {"id": "preco_pedido", "tipo": "opcao", "rotulo": "O preço pedido de R$ 90 milhões para as ações está:", "obrigatorio": true, "opcoes": ["Acima da sua faixa", "Dentro da sua faixa", "Abaixo da sua faixa"]}, {"id": "ev_wacc_14", "tipo": "numerico", "rotulo": "EV pelo DCF com WACC de 14%", "obrigatorio": true, "unidade": "R$ milhões", "dica": "Use vírgula como separador decimal."}, {"id": "ev_wacc_16", "tipo": "numerico", "rotulo": "EV pelo DCF com WACC de 16%", "obrigatorio": true, "unidade": "R$ milhões", "dica": "Use vírgula como separador decimal."}, {"id": "conclusao", "tipo": "texto", "rotulo": "Conclusão: justifique a faixa, como pesou cada método e a avaliação do preço pedido.", "obrigatorio": true, "limiteCaracteres": 1200}, {"id": "positivos_riscos", "tipo": "texto", "rotulo": "Principais pontos positivos e riscos da Aurora para os compradores.", "obrigatorio": true, "limiteCaracteres": 800}, {"id": "confirmar", "tipo": "texto", "rotulo": "Três informações a confirmar antes de negociar.", "obrigatorio": true, "limiteCaracteres": 600}, {"id": "planilha_final", "tipo": "arquivo", "rotulo": "Anexar a planilha completa (opcional)", "obrigatorio": false, "dica": "PDF, XLSX ou CSV, até 10 MB"}]$$::jsonb, NULL, $${"referencias": {"ev_wacc_14": 98.6, "ev_wacc_16": 81.0, "acoesDCF": 75.0, "acoesComps": 65.2, "acoesTransacoes": 69.4, "tolerancia_relativa": 0.02}, "avaliacao": "Não impor conclusão única nem média dos métodos. Com a seleção de referência, as ações valem cerca de 65 a 75 (comps 65,2; transações 69,4; DCF 75,0), abaixo do preço pedido de 90; o EV do DCF (89,0) é quase igual ao preço pedido, então verificar se a participante não confunde EV com valor das ações. Aceitar faixas diferentes se justificadas por escolhas defensáveis. Verificar sensibilidade coerente (WACC maior reduz o valor), pontos positivos e riscos específicos, e três informações a confirmar relevantes (por exemplo, dependência das quatro empresas indicadoras, impacto do on-line, custo de atualização dos equipamentos, base única de alunos, saída das fundadoras).", "perguntasDeDefesa": ["Por que escolheu essas referências e não as outras?", "O que mudaria sua faixa de valor?", "Como o preço pedido se compara ao seu EV e ao valor das ações?", "Qual a parcela do valor vindo do valor terminal?"]}$$::jsonb)
ON CONFLICT (id) DO NOTHING;
